function classify(url) {
  if (url.includes('/events/homepage_lane')) return 'lane-xhr';
  if (/\.(?:avif|webp|png|jpe?g)(?:\?|$)/i.test(url) || url.includes('/rails/active_storage/') || url.includes('/media_proxy/')) return 'image';
  if (/\.(?:js|css)(?:\?|$)/i.test(url)) return 'asset';
  return 'other';
}

function interesting(url) {
  const c = classify(url);
  return c === 'lane-xhr' || c === 'image';
}

